tokens.css:
--color-bg: #fbf6ef;
--color-surface: #fffdf9;
--color-text: #2a1f61;
--color-text-muted: #6e5f52;
--color-border: #e4d9c9;
--color-primary: #2a1f61;
--color-on-primary: #ffffff;
--color-accent: #d9a441;
--color-on-accent: #2a1f61;
--font-display: "Archivo", system-ui, sans-serif;
--font-body: "Manrope", system-ui, sans-serif;
--text-sm: 13px;
--text-base: 16px;
--text-lg: 20px;
--text-xl: 25px;
--text-2xl: 31px;
--text-3xl: 39px;
--radius-control: 6px;
--radius-card: 12px;
--space-section: 120px;
--shadow-card: 0 1px 2px color-mix(in oklab, var(--color-text) 8%, transparent), 0 10px 30px color-mix(in oklab, var(--color-text) 12%, transparent);
